{"packet_id":"D043-02","doc_id":"D043","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles RSO/JCO relocation assistance","requirement":"A landlord who displaces a tenant under the RSO or JCO must pay relocation assistance of $11,000 to $27,400 per unit within 15 days of the eviction notice, paying the higher amount where more than one amount applies.","key_value":"$11,000 (eligible, under 3 years) to $27,400 (qualified, 3+ years or low income), per unit","coverage_conditions":"Tenants displaced from RSO- or JCO-covered rental units; the amount depends on household income, eligible or qualified status and length of tenancy. Amounts effective July 1, 2026 through June 30, 2027.","applicability":{"conditions":[],"per_tenancy":"Amounts depend on tenant income, whether the tenant is eligible or qualified (62 or older, handicapped or disabled, or with minor dependent children), and length of tenancy (under 3 years vs. 3 or more years).","coverage_quotes":[]},"exemptions":"Single-family dwellings owned by a natural person owning no more than four dwelling units: one month's rent instead. A landlord may offset the tenant's accumulated rent against relocation assistance unless the tenant was ordered to vacate an unpermitted dwelling.","penalty":"The tenant may raise the landlord's failure to provide relocation assistance as an affirmative defense in an eviction action and may file a complaint with LAHD.","effective_date":"2026-07-01","valid_through":"2027-06-30","citation":"Los Angeles Rent Stabilization Ordinance (L.A.M.C. §151.00 et seq.); Los Angeles Just Cause Ordinance (L.A.M.C. §165.00 et seq.)","quoted_span":"Eligible Tenant $11,000 $14,400\nQualified Tenant $23,150 $27,400","interaction":null,"relations":[],"confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D043-02","doc_id":"D043","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Resident Protections Ordinance / Housing Crisis Act relocation for demolition for new construction","requirement":"Where a landlord demolishes occupied units to build new housing, only lower income households must receive relocation payments, at least the RSO or JCO amounts, increased only where city or state law requires.","key_value":"$87,450 (Low Income) to $115,480 (Extremely Low Income) per household","coverage_conditions":"Low, Very Low and Extremely Low income households displaced by demolition of a Protected Unit for new construction. Amounts effective July 1, 2026 through June 30, 2027.","applicability":{"conditions":[],"per_tenancy":"Applies where a Protected Unit is demolished so the owner can build new construction and the displaced household is lower income.","coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":"2026-07-01","valid_through":"2027-06-30","citation":"City of Los Angeles Resident Protections Ordinance (Cal. Gov. Code § 66300.6(b)(4)(A))","quoted_span":"ONLY lower income households being displaced for the purpose of demolition of their units where the owner will replace the units with new construction must receive relocation payment","interaction":null,"relations":[],"confidence":0.75,"conflict_flag":false,"conflict_note":null}
